§2.2“多选一”动作开关的控制程序——实现B
// 端口检测、动作执行
if ( Buttons.RUNING_MODE == Buttons.NONE ) {
// 只在非任务执行过程中监测和响应按钮动作
for ( int i = 0; i < Buttons.NumButtons; i++ ) {            // 逐个按钮开关循环
Buttons.PortVolt[i] = digitalRead(Buttons.pinBUT[i]);     // 监测每个按钮端口的电平
if ( Buttons.PortVolt[i] < Buttons.PortVoltLast[i]  ) {   // 当监测到按钮开关被按下(端口电平由高转低)
Buttons.RUNING_MODE = i;                                // 定义将要执行的任务代码
Buttons.tstart = last_loop_time;                        // 记录按钮被按下的时间，近似为任务的开始时间
}
Buttons.PortVoltLast[i] = Buttons.PortVolt[i];            // 记录按钮端口的当前电平，作为下一次监测的参考
}
}
else {
// 任务代码已定义，则执行相应的任务
float t = (last_loop_time - Buttons.tstart) * 1.0e-6;       
// 计算任务开始至当前的时间差
Slider.slider_speed = (*Buttons.pCBfunc[Buttons.RUNING_MODE])(t);     // 根据任务类型和时间差更新滑台的移动速度
}

